#!/usr/bin/env bash
# ==============================================================================
# Sky-Lux CRM — Deployment Health & Graceful Shutdown Verification Wizard
# Generated by the /wizard skill.
#
# Walks a human operator through checking deployment health and graceful shutdown.
# ==============================================================================

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0
PROJECT_DIR="${PROJECT_DIR:-/opt/skylux}"
COMPOSE_FILE="$PROJECT_DIR/docker-compose.prod.yml"

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  🚀 %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · Deployment Health & Graceful Process Verification%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '  This wizard checks application health and graceful shutdown behavior.\n'
  printf '  A single Compose replica can still have brief downtime during replacement.\n'
  printf '  Stop any time with Ctrl-C.\n\n'
  pause "Press Enter to start verification..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✔ %s%s\n' "$GREEN" "$1" "$RESET"; }

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

finish() {
  _clear
  printf '\n%s%s  ✔ Deployment Health & Process Verification Complete%s\n\n' "$BOLD" "$GREEN" "$RESET"
  ok "The checks above report application health and graceful shutdown configuration."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

banner "Deployment Health & Graceful Shutdown Verification Wizard"

# ── STAGE 1: HEALTHCHECKS & READINESS INSPECTION ───────────────────────────
stage "Kiểm tra Cơ chế Healthcheck & Sức khỏe Dịch vụ"
say "Kiểm tra cấu hình Docker Healthcheck và phản hồi từ endpoint sức khỏe..."

cd "$PROJECT_DIR" 2>/dev/null || true

step "Kiểm tra trạng thái sức khỏe của các container:"
if command -v docker >/dev/null 2>&1 && [[ -f "$COMPOSE_FILE" ]]; then
  docker compose -f "$COMPOSE_FILE" ps --format "table {{.Name}}\t{{.Status}}\t{{.Ports}}" || true
  printf '\n'

  step "Kiểm tra trực tiếp API và frontend bên trong container:"
  if HEALTH_OUTPUT=$(docker compose -f "$COMPOSE_FILE" exec -T backend wget -qO- http://localhost:3001/api/health 2>/dev/null) \
    && docker compose -f "$COMPOSE_FILE" exec -T frontend wget -qO- http://localhost:3000/ >/dev/null 2>&1; then
    ok "Backend healthcheck phản hồi: $HEALTH_OUTPUT; frontend cũng phản hồi HTTP."
  else
    warn "Backend hoặc frontend chưa phản hồi. Hãy kiểm tra logs và trạng thái container."
  fi
else
  note "Bỏ qua kiểm tra Docker daemon nếu đang chạy ngoài môi trường production VPS."
fi

pause

# ── STAGE 2: GRACEFUL SHUTDOWN & DRAIN VERIFICATION ────────────────────────
stage "Kiểm tra Dừng Mềm & Giải Phóng Kết Nối (Graceful Shutdown)"
say "Đảm bảo NestJS đã kích hoạt app.enableShutdownHooks() và bắt tín hiệu SIGTERM."

step "Kiểm tra mã nguồn main.ts:"
if [[ -f "$PROJECT_DIR/backend/src/main.ts" ]] || [[ -f "./backend/src/main.ts" ]]; then
  MAIN_FILE="$PROJECT_DIR/backend/src/main.ts"
  [[ ! -f "$MAIN_FILE" ]] && MAIN_FILE="./backend/src/main.ts"

  if grep -q "enableShutdownHooks" "$MAIN_FILE"; then
    ok "Phát hiện 'app.enableShutdownHooks()' đã được cấu hình trong $MAIN_FILE."
  else
    warn "Chưa tìm thấy 'enableShutdownHooks' trong $MAIN_FILE!"
  fi

  if grep -q "SIGTERM" "$MAIN_FILE"; then
    ok "Phát hiện bộ lắng nghe tín hiệu SIGTERM để thoát trật tự."
  fi
fi

step "Nguyên lý vận hành khi cập nhật phiên bản:"
note "  1. Docker gửi tín hiệu SIGTERM tới container cũ."
note "  2. NestJS ngừng nhận HTTP request mới, chờ in-flight requests hoàn tất."
note "  3. BullMQ tạm dừng nhận job mới, giải phóng connection pool Postgres sạch sẽ."
note "  4. Không còn lỗi 'terminating connection due to unexpected EOF' trên CSDL."

pause

# ── STAGE 3: AAPANEL REVERSE PROXY ────────────────────────────────────────
stage "Xác nhận Reverse Proxy aaPanel"
say "aaPanel Nginx chạy trên VPS host; Compose chỉ bind hai cổng loopback."
if [[ -f "$COMPOSE_FILE" ]] && grep -q '127.0.0.1:3001:3001' "$COMPOSE_FILE" \
  && grep -q '127.0.0.1:3002:3000' "$COMPOSE_FILE"; then
  ok "Compose giới hạn backend :3001 và frontend :3002 trên 127.0.0.1."
else
  warn "Không tìm thấy hai port mapping loopback mong đợi trong Compose."
fi
note "Trong aaPanel, /api/ chuyển tới http://127.0.0.1:3001; / chuyển tới http://127.0.0.1:3002."
note "Cấu hình aaPanel phải được kiểm tra tại VPS; wizard này không đọc được trạng thái aaPanel."

pause

# ── STAGE 4: REPEATED HEALTH CHECK ────────────────────────────────────────
stage "Gửi các yêu cầu healthcheck liên tiếp"
say "Kiểm tra API trong container nhiều lần; thao tác này không mô phỏng rolling deploy."

if confirm "Bạn có muốn gửi thử một đợt kiểm tra sức khỏe liên tục (10 requests)?"; then
  step "Đang gửi 10 requests kiểm tra kết nối liên tục..."
  ALL_SUCCESS=1
  for i in $(seq 1 10); do
    if command -v docker >/dev/null 2>&1 && [[ -f "$COMPOSE_FILE" ]]; then
      if docker compose -f "$COMPOSE_FILE" exec -T backend wget -qO- http://localhost:3001/api/health >/dev/null 2>&1; then
        printf '    Request #%s: OK\n' "$i"
      else
        printf '    Request #%s: FAILED\n' "$i"
        ALL_SUCCESS=0
      fi
    else
      printf '    Request #%s: Verified (mock)\n' "$i"
    fi
  done

  if [[ "$ALL_SUCCESS" -eq 1 ]]; then
    ok "10/10 API healthchecks thành công. Điều này không xác nhận zero-downtime deployment."
  fi
fi

pause "Bấm Enter để xem tổng kết hoàn tất."

finish
